  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

/* ── Skip link ────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--clr-accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: 0 0 var(--radius) var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 999;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 0;
  outline: 3px solid #fff;
  outline-offset: 2px;
}

/* ── Header ───────────────────────────────────────────────────── */
.site-header {
  background: var(--clr-surface);
  border-bottom: 1px solid var(--clr-border);
  padding: 0.875rem 1.5rem;
}
.header-inner {
  max-width: 760px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.logo {
  font-size: 1.5rem;
  line-height: 1;
}
.site-name {
  font-size: 1.125rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--clr-text);
}

/* ── Hero ─────────────────────────────────────────────────────── */
.hero {
  max-width: 760px;
  margin: 3rem auto 2rem;
  padding: 0 1.5rem;
  text-align: center;
}
.hero h1 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.2;
  color: var(--clr-text);
}
.hero-sub {
  margin-top: 0.625rem;
  font-size: 1.0625rem;
  color: var(--clr-text-muted);
}

/* ── FAQ section ──────────────────────────────────────────────── */
.faq-section {
  max-width: 760px;
  margin: 0 auto 4rem;
  padding: 0 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* ── Disclosure widget (.example wrapper) ─────────────────────── */
.example {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-card);
  overflow: hidden;
  transition: box-shadow var(--transition), border-color var(--transition);
}
.example:has(.question[aria-expanded="true"]) {
  border-color: var(--clr-accent);
  box-shadow: var(--shadow-card-hover);
}

/* ── Question button ──────────────────────────────────────────── */
.question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.125rem 1.375rem;
  background: transparent;
  border: none;
  cursor: pointer;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  color: var(--clr-text);
  text-align: left;
  transition: background var(--transition), color var(--transition);
}
.question:hover {
  background: #f0f1f9;
}
.question:focus-visible {
  outline: 3px solid var(--clr-accent);
  outline-offset: -3px;
  border-radius: calc(var(--radius) - 1px);
}
.question[aria-expanded="true"] {
  color: var(--clr-accent);
}

.question-text {
  flex: 1;
}

/* ── Chevron icon ─────────────────────────────────────────────── */
.chevron {
  flex-shrink: 0;
  width: 1.25rem;
  height: 1.25rem;
  border-right: 2.5px solid currentColor;
  border-bottom: 2.5px solid currentColor;
  transform: rotate(45deg) translateY(-3px);
  transition: transform var(--transition), color var(--transition);
  color: var(--clr-text-muted);
}
.question[aria-expanded="true"] .chevron {
  transform: rotate(-135deg) translateY(-3px);
  color: var(--clr-accent);
}

/* ── Answer panel (.details) ──────────────────────────────────── */
.details {
  padding: 0 1.375rem 1.375rem;
  background: var(--clr-answer-bg);
  border-top: 1px solid var(--clr-border);
  animation: fadeSlideIn 180ms ease both;
}
.details p {
  font-size: 0.9375rem;
  color: var(--clr-text-muted);
  line-height: 1.7;
}
.details p + p {
  margin-top: 0.75rem;
}
.details strong {
  color: var(--clr-text);
  font-weight: 600;
}
.details em {
  font-style: italic;
}

@keyframes fadeSlideIn {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ── Footer ───────────────────────────────────────────────────── */
.site-footer {
  margin-top: auto;
  padding: 1.5rem;
  text-align: center;
  font-size: 0.875rem;
  color: var(--clr-text-muted);
  border-top: 1px solid var(--clr-border);
}

/* ── Reduced motion ───────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* ── Forced colors ────────────────────────────────────────────── */
@media (forced-colors: active) {
  .example {
    border: 1px solid ButtonBorder;
  }
  .question {
    color: ButtonText;
    background: ButtonFace;
  }
  .question:focus-visible {
    outline: 3px solid Highlight;
  }
  .chevron {
    border-color: ButtonText;
  }
  .details {
    background: Canvas;
    border-top: 1px solid ButtonBorder;
  }
}

/* ── Reflow / narrow viewports ────────────────────────────────── */
@media (max-width: 400px) {
  .question {
    padding: 1rem 1rem;
  }
  .details {
    padding: 0 1rem 1rem;
  }
}
